style.css:
@-moz-document domain("atlassian.net") {
div[data-testid="platform-board-kit.ui.swimlane.swimlane-content"] {
	width: 100%;
}

div[data-testid="platform-board-kit.ui.swimlane.swimlane-content"] button {
	width: 100%;
}

div[data-testid="platform-board-kit.ui.swimlane.summary-section"] {
  text-align: left;
}

.css-bitnwz div:nth-child(1) {
  order: 1;
}

.css-bitnwz div:nth-child(2) {
  order: 2;
}

.css-bitnwz div:nth-child(3) {
  order: 4;
}

.css-bitnwz div:nth-child(4) {
  order: 5;
}

.css-bitnwz div:nth-child(5) {
  order: 6;
}

.css-bitnwz div:nth-child(6) {
  text-align: right;
  flex-direction: row-reverse;
  order: 3;
}

.css-bitnwz div:nth-child(7)
{
	order: 7;
}
}
